/** utils/webhook-manager.js
 * Webhook Manager
 * Parses Africa's Talking callbacks (SMS + Voice) into a normalized shape.
 */

class WebhookManager {
  constructor() {}

  /**
   * Parse an Africa's Talking callback payload.
   * Returns either an 'sms' event or an 'ivr' event, or null if unrecognized.
   */
  parseAfricasTalkingPayload(payload) {
    try {
      // ---- SMS incoming message (UNCHANGED) ----
      if (payload.text && payload.from && !payload.sessionId) {
        return {
          type: 'sms',
          sessionId: payload.sessionId || payload.linkId || this.extractSessionFromText(payload),
          phoneNumber: this.formatPhoneNumber(payload.from),
          content: payload.text,
          messageId: payload.id,
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }

      // ---- Voice / IVR callback ----
      // Africa's Talking posts sessionId, direction, callerNumber, destinationNumber,
      // isActive, dtmfDigits, recordingUrl, durationInSeconds, etc. on every event of a
      // call's lifecycle (call connected, digits collected, recording done, call ended).
      if (payload.sessionId && (payload.direction || payload.isActive !== undefined || payload.dtmfDigits !== undefined)) {
        const direction = payload.direction || 'Inbound';
        const isActive = payload.isActive === '1' || payload.isActive === 1 || payload.isActive === true;

        // For an inbound call, the caller is callerNumber. For a call we originated
        // (outbound), the human we're talking to is the destinationNumber.
        const userPhoneNumber = direction === 'Outbound' ? payload.destinationNumber : payload.callerNumber;

        return {
          type: 'ivr',
          sessionId: payload.sessionId,
          direction,
          phoneNumber: this.formatPhoneNumber(userPhoneNumber),
          content: payload.dtmfDigits || '',
          dtmfDigits: payload.dtmfDigits || null,
          recordingUrl: payload.recordingUrl || null,
          isActive,
          // No dtmf/recording yet + still active = this is the "call just connected" event
          isCallStart: isActive && !payload.dtmfDigits && !payload.recordingUrl,
          durationInSeconds: payload.durationInSeconds,
          hangupCause: payload.hangupCause || null,
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }

      return null;
    } catch (error) {
      console.error('Error parsing Africa\'s Talking payload:', error);
      return null;
    }
  }

  /**
   * Extract session ID from SMS text (if embedded)
   * Format: [SESSION:xyz] message content
   */
  extractSessionFromText(payload) {
    const match = payload.text?.match(/\[SESSION:([^\]]+)\]/);
    return match ? match[1] : null;
  }

  /**
   * Format phone number to E.164
   */
  formatPhoneNumber(phoneNumber) {
    if (!phoneNumber) return null;

    let cleaned = phoneNumber.replace(/\D/g, '');

    if (!phoneNumber.startsWith('+')) {
      if (cleaned.length === 9) {
        cleaned = '250' + cleaned;
      } else if (cleaned.length === 10 && cleaned.startsWith('0')) {
        cleaned = '250' + cleaned.substring(1);
      }
    }

    return '+' + cleaned;
  }

  /**
   * Build webhook URL
   * @param {string} baseUrl - Base URL from .env
   * @param {string} path - Path from configuration
   */
  buildWebhookUrl(baseUrl, path) {
    if (!baseUrl) {
      throw new Error('Webhook base URL not configured in .env');
    }

    const cleanBase = baseUrl.replace(/\/$/, '');
    const cleanPath = path.startsWith('/') ? path : '/' + path;

    return cleanBase + cleanPath;
  }
}

module.exports = WebhookManager;